mapper.select:

		/*selectSellerMpIvKtagPlanEntryPopList*/
			SELECT	
					DS_SEQ	,								 
					KTAG_QTY
					FROM ICOMKTAG			

              WHERE BUYER = #{BUYER}
                AND INV_NO =  #{INV_NO}
                AND INV_SEQ =  #{INV_SEQ}
                AND BUYER_ITEM_NO =  #{BUYER_ITEM_NO}
                ORDER BY DS_SEQ

mapper.update:
	/*deleteSellerMpIvKtagPlanEntryPop*/

			DELETE 
			    ICOMKTAG /* 회사별 코드관리 */
              WHERE BUYER = #{buyer}
                AND INV_NO =  #{inv_no}
                AND INV_SEQ =  #{inv_seq}
                AND BUYER_ITEM_NO =  #{buyer_item_no}

	/*insertSellerMpIvKtagPlanEntryPop*/

			INSERT INTO ICOMKTAG /* 회사별 코드관리 */
			(
			        BUYER
			      , INV_NO
			      , INV_SEQ
			      , BUYER_ITEM_NO
			      , DS_SEQ
			      , STATUS
			      , ADD_DATE
			      , ADD_TIME
			      , CHANGE_DATE
			      , CHANGE_TIME
			      , INV_QTY
                  , KTAG_QTY
                  , PO_NO
                  , PO_SEQ
			    )
			    VALUES 
			    (
			        #{buyer}
			      , #{inv_no}
			      , #{inv_seq}
			      , #{buyer_item_no}
			      , #{st_seq}
			      , 'C'
			      , to_char(sysdate,'YYYYMMDD')
			      , to_char(sysdate,'HH24MISS')
			      , to_char(sysdate,'YYYYMMDD')
			      , to_char(sysdate,'HH24MISS')
			      , #{inv_qty}
                  , #{cd_qty}
			      , #{po_no}
			      , #{po_seq}
			)
